-- ASSET-005: stock rooms: counted lines per location with reorder thresholds, every movement, and the purchase request a threshold raises.
CREATE TABLE work_stock_lines(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,location TEXT NOT NULL,location_key TEXT NOT NULL,item TEXT NOT NULL,item_key TEXT NOT NULL,kind TEXT NOT NULL,on_hand INTEGER NOT NULL,threshold INTEGER NOT NULL,reorder_quantity INTEGER NOT NULL,unit_cents INTEGER NOT NULL,buyer TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,latest_movement_id TEXT,UNIQUE(workspace_id,location_key,item_key));
CREATE TABLE work_stock_movements(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,line_id TEXT NOT NULL,kind TEXT NOT NULL,quantity INTEGER NOT NULL,person_id TEXT,purchase_id TEXT,evidence TEXT NOT NULL,actor_id TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE work_stock_purchases(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,line_id TEXT NOT NULL,quantity INTEGER NOT NULL,unit_cents INTEGER NOT NULL,estimate_cents INTEGER NOT NULL,buyer TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'raised',raised_by_movement_id TEXT NOT NULL,raised_at TEXT NOT NULL,order_reference TEXT,decided_by TEXT,decided_at TEXT,reason TEXT,received_at TEXT);
CREATE UNIQUE INDEX work_stock_purchases_open ON work_stock_purchases(workspace_id,line_id) WHERE state IN ('raised','ordered');
